?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Utilisateurs inscrits</title><style>body{font-family:Arial,sans-serif;margin:24px;color:#172b3a}h1{color:#082c47}table{border-collapse:collapse;width:100%}th,td{border:1px solid #ccd5dc;padding:10px;text-align:left}th{background:#082c47;color:white}a{color:#075985}</style></head><body><h1>Utilisateurs inscrits</h1><p><a href="dashboard.php">← Retour aux soumissions</a>　<a href="logout.php">Déconnexion</a></p><?php if(isset($_GET["saved"])):?><p>Compte mis à jour.</p><?php elseif(isset($_GET["deleted"])):?><p>Utilisateur et projets associés supprimés.</p><?php endif;?><table><thead><tr><th>Compte (modifiable)</th><th>Inscription</th><th>Projets</th><th>Action</th></tr></thead><tbody><?php if($result&&mysqli_num_rows($result)):while($u=mysqli_fetch_assoc($result)):?><tr><td><form id="user-<?=(int)$u["id"]?>" method="post" action="save_user.php"><input type="hidden" name="id" value="<?=(int)$u["id"]?>"></form><input form="user-<?=(int)$u["id"]?>" name="fullname" maxlength="150" required value="<?=h($u["fullname"])?>"><br><input form="user-<?=(int)$u["id"]?>" type="email" name="email" maxlength="255" required value="<?=h($u["email"])?>"></td><td><?=h($u["created_at"])?></td><td><?=(int)$u["project_count"]?></td><td><button form="user-<?=(int)$u["id"]?>" name="action" value="update">Enregistrer</button><form method="post" action="save_user.php" onsubmit="return confirm('Supprimer cet utilisateur et tous ses projets ?')"><input type="hidden" name="id" value="<?=(int)$u["id"]?>"><button name="action" value="delete" style="background:#a33a3a;color:#fff;margin-top:6px">Supprimer</button></form></td></tr><?php endwhile;else:?><tr><td colspan="4">Aucun utilisateur inscrit.</td></tr><?php endif?></tbody></table></body></html>